type Json=Record<string,any>;
const applicationReporting=new AsyncLocalStorage<{silent:boolean}>();
const sha=(bytes:Uint8Array|string)=>createHash('sha256').update(bytes).digest('hex');
const fail=(message:string):never=>{throw Error('APPLICATION_PROFILE_'+message);};
const closed=(value:any,keys:readonly string[],required:readonly string[]=keys):Json=>{if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!keys.includes(k))||required.some(k=>!Object.hasOwn(value,k)))fail('INVALID_CLOSED_PROJECT: '+keys.join(','));return value;};
